{"file_path": "frappe-bench/apps/frappe/frappe/public/js/hot-reload.js", "initial_content": "/**
 * Frappe Hot-Reload Module
 * Enables instant asset updates during development without manual page reload
 *
 * Features:
 * - Detects build events via Socket.IO
 * - Smart refresh strategy (CSS inline update, JS reload)
 * - Preserves application state when possible
 * - Shows build status and errors in console
 */

(function() {
	"use strict";

	// Only enable in development mode
	if (!frappe.boot || frappe.boot.disable_hot_reload) {
		return;
	}

	const HotReloader = {
		enabled: true,
		isReloading: false,
		lastBuildTime: 0,
		debounceDelay: 300, // ms - prevent multiple rapid reloads
		cssUpdateMap: new Map(),

		init() {
			if (!this.enabled) return;

			this.setupSocketListener();
			this.logStatus("Hot-reload enabled. Watching for changes...");
		},

		setupSocketListener() {
			if (!frappe.realtime) {
				console.warn("[Hot-Reload] Socket.IO not available");
				return;
			}

			// Listen for build events from esbuild watch
			frappe.realtime.on("build_event", (data) => {
				this.handleBuildEvent(data);
			});

			this.logStatus("Socket.IO listener attached");
		},

		handleBuildEvent(data) {
			if (this.isReloading) return;

			const now = Date.now();
			if (now - this.lastBuildTime < this.debounceDelay) {
				return; // Skip if within debounce window
			}

			this.lastBuildTime = now;

			if (data.error) {
				this.handleBuildError(data);
			} else if (data.success && data.live_reload) {
				this.handleBuildSuccess(data);
			}
		},

		handleBuildError(data) {
			console.error("[Hot-Reload] Build Error:", data);
			if (data.formatted) {
				data.formatted.forEach((msg) => {
					console.error(msg);
				});
			}
			this.showNotification("Build Error - Check Console", "error");
		},

		async handleBuildSuccess(data) {
			const { changed_files = [] } = data;

			if (!changed_files || changed_files.length === 0) {
				return;
			}

			console.log(
				`[Hot-Reload] ${changed_files.length} file(s) changed:`,
				changed_files
			);

			// Categorize changed files
			const cssFiles = changed_files.filter((f) => f.endsWith(".css"));
			const jsFiles = changed_files.filter((f) => f.endsWith(".js"));

			// Try CSS hot-update first
			if (cssFiles.length > 0 && jsFiles.length === 0) {
				const success = await this.updateStylesheets(cssFiles);
				if (success) {
					this.showNotification(
						`CSS updated (${cssFiles.length} file${cssFiles.length > 1 ? "s" : ""})`,
						"success"
					);
					return;
				}
			}

			// For JS changes or mixed changes, reload page
			if (jsFiles.length > 0) {
				this.reloadPage(changed_files);
			}
		},

		async updateStylesheets(changedCssFiles) {
			try {
				const stylesheets = document.querySelectorAll("link[rel='stylesheet']");
				let updated = 0;

				for (const link of stylesheets) {
					const href = link.getAttribute("href");
					if (!href) continue;

					// Check if this stylesheet was changed
					const isChanged = changedCssFiles.some((file) =>
						href.includes(file.replace(/^\//, "").split("?")[0])
					);

					if (isChanged) {
						// Add cache-buster query parameter
						const newHref = this.addCacheBuster(href);
						link.setAttribute("href", newHref);
						updated++;

						this.logStatus(`Updated stylesheet: ${href}`);
					}
				}

				return updated > 0;
			} catch (error) {
				console.error("[Hot-Reload] CSS update failed:", error);
				return false;
			}
		},

		addCacheBuster(url) {
			const timestamp = Date.now();
			const separator = url.includes("?") ? "&" : "?";
			return `${url}${separator}t=${timestamp}`;
		},

		reloadPage(changedFiles) {
			if (this.isReloading) return;

			this.isReloading = true;

			// Check for unsaved form data
			const unsavedForms = this.getUnsavedForms();
			if (unsavedForms.length > 0) {
				const formNames = unsavedForms.map((f) => f.doctype).join(", ");
				console.warn(
					`[Hot-Reload] Unsaved changes detected in: ${formNames}. Reload will be skipped to preserve state.`
				);
				this.isReloading = false;
				this.showNotification(
					"Save changes to reload",
					"warning"
				);
				return;
			}

			this.showNotification("Reloading...", "info");
			this.logStatus(
				`Reloading page due to: ${changedFiles.join(", ")}`
			);

			// Small delay to ensure assets are ready
			setTimeout(() => {
				location.reload();
			}, 200);
		},

		getUnsavedForms() {
			try {
				if (typeof cur_frm !== "undefined" && cur_frm && cur_frm.dirty) {
					return [cur_frm];
				}
			} catch (e) {
				// ignore
			}
			return [];
		},

		showNotification(message, type = "info") {
			// Only show notification if not in background
			if (document.hidden) return;

			try {
				frappe.show_alert({
					message,
					indicator: type,
				});
			} catch (error) {
				console.log(`[Hot-Reload] ${type.toUpperCase()}: ${message}`);
			}
		},

		logStatus(message) {
			const timestamp = new Date().toLocaleTimeString();
			console.log(`[Hot-Reload ${timestamp}] ${message}`);
		},
	};

	// Initialize when Frappe is ready
	if (document.readyState === "loading") {
		document.addEventListener("DOMContentLoaded", () => {
			setTimeout(() => {
				HotReloader.init();
			}, 500);
		});
	} else {
		setTimeout(() => {
			HotReloader.init();
		}, 500);
	}

	// Expose for debugging
	window.__frappe_hot_reload__ = HotReloader;
})();
"}

